:root {
  --todo-black: #1E1E1E;
  --todo-white: #FFFFFF;
  --todo-error: #CC3D3D;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--todo-white);
  color: var(--todo-black);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button,
input {
  font: inherit;
}

.page-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 64px 24px;
}

.back-navigation {
  width: min(100%, 900px);
  margin-bottom: 20px;
}

.back-navigation__link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border: 4px solid var(--todo-black);
  border-radius: 50%;
  color: var(--todo-black);
  font-size: 42px;
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
}

.back-navigation__link:hover,
.back-navigation__link:focus {
  background: var(--todo-black);
  color: var(--todo-white);
}

.todo-panel {
  width: min(100%, 900px);
  overflow: hidden;
  background: var(--todo-white);
  border: 4px solid var(--todo-black);
  border-radius: 18px;
}

.todo-panel__header {
  padding: 18px 24px;
  background: var(--todo-black);
}

.todo-panel__header--with-action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.todo-panel__header h1,
.todo-list-name-form__input {
  margin: 0;
  font-style: normal;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  text-align: center;
  color: var(--todo-white);
  vertical-align: middle;
}

.todo-list-name-frame {
  flex: 1 1 auto;
  min-width: 0;
}

.todo-list-name__link {
  color: inherit;
  text-decoration: none;
}

.todo-list-name__link:hover,
.todo-list-name__link:focus {
  text-decoration: underline;
}

.todo-list-name-form {
  position: relative;
}

.todo-list-name-form__input {
  width: 100%;
  min-height: 72px;
  padding: 4px 204px 4px 24px;
  border: 4px solid var(--todo-white);
  border-radius: 24px;
  background: var(--todo-black);
  outline: none;
}

.todo-list-name-form__overlay {
  position: absolute;
  top: 50%;
  right: 10px;
  display: flex;
  gap: 8px;
  padding: 6px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.14);
  transform: translateY(-50%);
}

.todo-list-name-form__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 14px;
  border: 2px solid var(--todo-white);
  border-radius: 999px;
  background: var(--todo-white);
  color: var(--todo-black);
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
}

.todo-list-name-form__button--cancel {
  background: var(--todo-black);
  color: var(--todo-white);
}

.todo-list-name-form__errors {
  margin-bottom: 8px;
  padding: 8px 12px;
  border-radius: 12px;
  background: var(--todo-white);
  color: var(--todo-error);
  font-size: 16px;
  font-weight: 700;
  text-align: center;
}

.todo-list-name-form__errors p {
  margin: 0;
}

.todo-panel__body {
  display: flex;
  flex-direction: column;
  gap: 28px;
  padding: 48px;
}

.inline-create-form {
  position: relative;
  width: 100%;
}

.text-input {
  width: 100%;
  min-height: 86px;
  padding: 18px 112px 18px 36px;
  border: 4px solid var(--todo-black);
  border-radius: 36px;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: left;
  outline: none;
}

.text-input::placeholder {
  color: rgba(30, 30, 30, 0.8);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: left;
}

.input-action {
  position: absolute;
  top: 50%;
  right: 0;
  width: 86px;
  height: 86px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  transform: translateY(-50%);
  cursor: pointer;
}

.error-overlay {
  position: fixed;
  z-index: 1000;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 24px;
}

.error-box {
  position: relative;
  width: min(100%, 900px);
  max-height: 100%;
  overflow-y: auto;
  padding: 64px 72px 48px;
  border: 4px solid var(--todo-error);
  border-radius: 36px;
  background: var(--todo-white);
  color: var(--todo-error);
  box-shadow: 0 12px 40px rgba(30, 30, 30, 0.24);
}

.error-box__close {
  position: absolute;
  top: 16px;
  right: 20px;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--todo-error);
  font-size: 44px;
  line-height: 1;
  cursor: pointer;
}

.error-box p {
  margin: 0;
  color: var(--todo-error);
  font-size: 32px;
  line-height: 120%;
  text-align: center;
}

.error-box p + p {
  margin-top: 12px;
}

.items-list {
  display: block;
}

.items-list--scrollable {
  max-height: calc(6 * 64px + 5 * 24px);
  overflow-y: auto;
}

.empty-state {
  margin: 0;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: center;
  vertical-align: middle;
}

.pagination-frame__loading {
  margin: 0;
  color: var(--todo-black);
  font-weight: 400;

[160 more lines in file. Use offset=301 to continue.]

  align-items: center;
  justify-content: center;
}

.complete-all-button,
.complete-all-button img {
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
}

.icon-button,
.icon-button img {
  width: 64px;
  height: 64px;
}

@media (max-width: 640px) {
  .page-shell {
    padding: 24px 12px;
  }

  .back-navigation {
    margin-bottom: 16px;
  }

  .back-navigation__link {
    width: 48px;
    height: 48px;
    font-size: 36px;
  }

  .todo-panel__header h1,
  .todo-list-name-form__input {
    font-size: 36px;
    line-height: 44px;
  }

  .todo-list-name-form__input {
    padding-right: 24px;
    padding-bottom: 62px;
  }

  .todo-list-name-form__overlay {
    top: auto;
    right: 50%;
    bottom: 8px;
    transform: translateX(50%);
  }

  .todo-panel__body {
    padding: 28px 18px;
  }

  .error-overlay {
    padding: 24px 12px;
  }

  .error-box {
    padding: 56px 28px 32px;
  }

  .text-input,
  .text-input::placeholder,
  .todo-row__text,
  .empty-state,
  .error-box p {
    font-size: 24px;
  }
}

